package com.halftonestudio;
import java.util.*;
public class VinylEngineTest {
 static void ok(boolean a,String msg){if(!a)throw new AssertionError(msg);}
 static int[] source(int w,int h){int[] a=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int r=x*255/(w-1),g=y*255/(h-1),b=(x*13+y*7)%256;a[y*w+x]=0xff000000|(r<<16)|(g<<8)|b;}return a;}
 static void testPalette(){VinylEngine.Settings s=VinylEngine.Settings.defaults();for(int n=2;n<=8;n++){while(s.layers.size()<n)s.layers.add(new VinylEngine.Layer("Vinyl "+s.layers.size(),VinylEngine.START_COLORS[s.layers.size()]));while(s.layers.size()>n)s.layers.remove(s.layers.size()-1);s.mode=VinylEngine.MOSAIC;s.dither=VinylEngine.BAYER;s.layers.get(0).spacing=3f;VinylEngine.Result r=VinylEngine.generate(source(38,34),38,34,s);ok(r.shapes.size()==n,"expected "+n+" svg layers");for(int i=0;i<n;i++){String svg=VinylEngine.svg(r,i);ok(svg.contains("width=\""),"svg width");ok(svg.contains("height=\""),"svg height");ok(svg.contains("viewBox=\"0 0"),"svg viewBox");}ok(VinylEngine.validateMarks(r)==null,"marks clear");}}
 static void testMosaic(){VinylEngine.Settings s=VinylEngine.Settings.defaults();s.mode=VinylEngine.MOSAIC;s.layers.get(0).spacing=4;VinylEngine.Result r=VinylEngine.generate(source(32,32),32,32,s);ArrayList<float[]> rects=new ArrayList<>();for(List<VinylEngine.Shape> layer:r.shapes)for(VinylEngine.Shape p:layer){float[] b=p.bounds();for(float[] q:rects){float x=Math.min(b[2],q[2])-Math.max(b[0],q[0]),y=Math.min(b[3],q[3])-Math.max(b[1],q[1]);ok(x<=.0001||y<=.0001,"mosaic overlap");}rects.add(b);}ok(rects.size()>0,"mosaic not empty");}
 static void testLines(){VinylEngine.Settings s=VinylEngine.Settings.defaults();s.mode=VinylEngine.CMYK;s.pattern=VinylEngine.LINE;s.minimumMm=.35f;s.marginMm=4f;s.layers.get(0).spacing=3.2f;VinylEngine.Result r=VinylEngine.generate(source(40,35),40,35,s);int n=0;boolean many=false;for(VinylEngine.Shape p:r.shapes.get(0)){ok(!p.circle,"line must be polygon");if(p.xy.length>16)many=true;float[] b=p.bounds();ok(b[0]>=s.marginMm-.001&&b[2]<=s.widthMm-s.marginMm+.001,"line x boundary");ok(b[1]>=s.marginMm-.001&&b[3]<=r.heightMm-s.marginMm+.001,"line y boundary");n++;}ok(n>0&&many,"continuous width line geometry not generated");}
 static void testCurve(){float[] c={0,.05f,.7f,.9f,1};ok(VinylEngine.curve(.5f,c)>.69f&&VinylEngine.curve(.5f,c)<.71f,"curve sampling");}
 static void testMarks(){VinylEngine.Settings s=VinylEngine.Settings.defaults();s.mode=VinylEngine.MOSAIC;s.layers.get(0).spacing=5;VinylEngine.Result r=VinylEngine.generate(source(16,16),16,16,s);String reference=VinylEngine.svg(r,0);for(int i=1;i<4;i++){String svg=VinylEngine.svg(r,i);String marker=RegistrationMarks.svgMark(0,r.marks[0][0],r.marks[0][1],s.markSizeMm);ok(reference.contains(marker),"mark presence");ok(svg.contains(marker),"mark mismatch");}s.marks=new float[][]{{40,40},{42,42},{-4,-4},{160,160}};try{VinylEngine.generate(source(16,16),16,16,s);throw new AssertionError("invalid mark accepted");}catch(IllegalArgumentException expected){ok(expected.getMessage().contains("overlap"),"must reject overlapping registration marks");}}
 public static void main(String[] args){testPalette();testMosaic();testLines();testCurve();testMarks();System.out.println("PASS: 2-8 SVG layers, disjoint mosaics, continuous line polygons, curve mapping, shared marks");}
}
